INSERT INTO `vacancies` (`id`, `company_id`, `reference_number`, `title`, `designation`, `description`, `requirements`, `required_skills`, `location`, `employment_type`, `min_experience`, `min_relevant_experience`, `min_salary`, `max_salary`, `publish_date`, `expire_date`, `is_active`, `approval_status`, `rejection_reason`, `sub1_approved_by`, `sub1_approved_at`, `global_approved_by`, `global_approved_at`, `rejected_by`, `rejected_at`, `status`, `created_by`, `created_at`, `updated_at`, `hired_application_id`, `weight_skills`, `weight_experience`, `weight_qualification`, `weight_jd_alignment`, `weight_salary`) VALUES
('42', '3', 'GSH/2026/25/003', 'Internship - Software Developer (.Net)', 'Internship - Software Developer (.Net)', '• Male / Female Candidate\n• Age below 27 years.\n• Currently pursuing a Degree in Computer Science, Software Engineering, Information Technology, or a related field; recent graduates may also apply.\n• NIBM Diploma holders are encouraged to apply.\n• Basic knowledge of C# and the .NET Framework / .NET Core.\n• Familiarity with Java programming concepts.\n• Understanding of ASP.NET MVC or ASP.NET Core web application development.\n• Basic knowledge of HTML, CSS, and JavaScript.\n• Exposure to Angular or React will be considered an added advantage.\n• Understanding of Object-Oriented Programming (OOP) principles.\n• Familiarity with Git and version control practices.\n• Strong analytical and problem-solving skills.\n• Excellent communication skills and the ability to work effectively within a team environment.\n• A willingness to learn new technologies and adapt to evolving project requirements.', '• Assist in the design, development, testing, and maintenance of web applications using C#, Java, and ASP.NET Core.\n• Develop and consume RESTful APIs and integrate third-party services.\n• Write clean, scalable, and maintainable code following software development best practices and SOLID principles.\n• Participate in code reviews to ensure quality standards and continuous learning.\n• Work with SQL Server and Oracle databases to write optimized queries and manage database structures.\n• Support database operations using Entity Framework Core.\n• Collaborate with senior developers, product managers, and designers to transform business requirements into technical solutions.\n• Assist in debugging, troubleshooting, and resolving application issues.\n• Contribute to software documentation and technical discussions within the development team.\n', '.Net', 'colombo 2', 'Full-Time', '1-2 years', '1-2 years', NULL, NULL, '2026-06-18', '2026-07-11', '1', 'approved', NULL, '4', '2026-06-18 16:09:33', '994', '2026-06-18 16:10:25', NULL, NULL, 'approved', NULL, '2026-06-18 15:57:59', '2026-06-18 16:10:25', NULL, NULL, NULL, NULL, NULL, NULL),
('55', '2', 'ST/2026/26/001', 'Senior Executive – Human Resources (Payroll & Talent Development)', 'Senior Executive – Human Resources (Payroll & Talent Development)', '• Manage end-to-end non-executive payroll processes, ensuring accurate and timely payroll administration.\n• Handle employee resignations, terminations, attendance administration, overtime tracking, shift changes,and payroll-related system updates.\n• Maintain and update employee records, HRIS data, and organizational structure information.\n• Coordinate employee training programs, assessments, and talent development initiatives.\n• Support performance management activities, including annual appraisals, promotions, and internal\ninterviews.\n• Collaborate with department heads\nto identify employee development opportunities and succession planning\nrequirements.\n• Prepare and issue\nemployee-related documentation, including service letters, salary\nconfirmation letters, bank letters, and other HR correspondence.\n• Process EPF/ETF claims and ensure\ncompliance with company policies and statutory requirements.\n• Organize employee engagement\nactivities and company events in line with the annual event calendar.\n• Provide administrative support\nfor HR operations and perform any other duties assigned by management.', '• Bachelor\'s Degree in Human Resources Management, Business Management, or a related discipline.\n• Minimum 2–3 years of experience in Human Resources, preferably in payroll administration and talent\ndevelopment.\n• Strong knowledge of payrollprocessing, attendance management, labor regulations, and HR operations.\n• Experience working with HRIS and payroll systems is an added advantage.\n• Proficiency in Microsoft Office applications, particularly MS Excel.\n• Excellent organizational, communication, and interpersonal skills.\n• Strong analytical and problem-solving abilities with keen attention to detail.\n• Ability to handle confidential information with professionalism and integrity.\n• Capable of managing multiple priorities and meeting deadlines in a fast-paced environment.\n• Experience in employee training, performance management, and HR administration will be an added advantage.', 'Bachelor\'s Degree in Human Resources Management', 'boardroom', 'Full-Time', '1-2 years', '1-2 years', NULL, NULL, '2026-06-22', '2026-07-03', '1', 'approved', NULL, NULL, NULL, '994', '2026-06-22 11:01:56', NULL, NULL, 'approved', NULL, '2026-06-22 10:15:24', '2026-06-22 11:01:56', NULL, NULL, NULL, NULL, NULL, NULL),
('57', '3', 'GSH/2026/26/002', 'JavaScript Backend Developer (AI-Driven)', 'JavaScript Backend Developer (AI-Driven)', '2+ years of backend development experience.\nStrong JavaScript and Node.js skills.\nGood understanding of REST APIs and backend architecture.\nExperience with PostgreSQL, MySQL, MongoDB, or Redis.\nStrong debugging and troubleshooting abilities.\nFamiliarity with Git and AWS is a plus.\nUnderstanding of software engineering fundamentals, design patterns, and clean code principles.\nAbility to work independently and communicate effectively in English.', '2+ years of backend development experience.\nStrong JavaScript and Node.js skills.\nGood understanding of REST APIs and backend architecture.\nExperience with PostgreSQL, MySQL, MongoDB, or Redis.\nStrong debugging and troubleshooting abilities.\nFamiliarity with Git and AWS is a plus.\nUnderstanding of software engineering fundamentals, design patterns, and clean code principles.\nAbility to work independently and communicate effectively in English.', 'Experience with AI-powered applications,LLMs,or AI agents.,Knowledge of OpenAI,Claude,Gemini', 'Colombo 03', 'Full-Time', '1-2 years', '1-2 years', NULL, NULL, '2026-06-22', '2026-07-11', '1', 'approved', NULL, '4', '2026-06-22 15:17:27', '994', '2026-06-22 15:17:37', NULL, NULL, 'approved', NULL, '2026-06-22 13:55:38', '2026-06-22 15:17:37', NULL, NULL, NULL, NULL, NULL, NULL),
('59', '3', 'GSH/2026/26/003', 'ASSISTANT ACCOUNTANT', 'ASSISTANT ACCOUNTANT', 'YOUR  ROLE:\n\n•Preparing monthly, quarterly and annual financial statements for given entities at group level.\n•Reviewing financial statements for given entities at Group level.\n•Performing month-end General Ledger closing function.\n•Reconciling monthly intercompany balances and preparing periodic consolidated financial statements.\n•Prepare cash flow reports and annual budgets and forecasts.\n•Preparing management reports and month-end reports as requested by the management.\n•Preparing periodic tax computations and responsible for all RAMIS reporting requirements.\n•Laise with tax authorities/ consultants and coordinate all tax matters.\n•Laise with auditors/banks and other third parties.\n•Facilitate the team and ensure that they are in line with company policies and deadlines.', 'YOUR  PROFILE:\n\n•A Bachelor’s degree in Finance or Accounting from a recognized University or Institute.\n•Qualified in ICASL/CIMA/ACCA.\n•Minimum 07 years of overall experience and 03 years of experience in a similar role.\n•Sound knowledge of taxation, IRD related compliances and accounting standards.\n•Excellent leadership skills with a passion to deliver results.\n•Self motivated individual a team player to lead cross functional teams.\n•High standard of technical, analytical & reporting skills.\n•Fluency in written & spoken English.\n•Conversant with MS Office packages and proficiency in Advanced Excel.\n ', 'Qualified in ICASL/CIMA/ACCA', 'No. 7E, Postmasters Place, Off Templers Road, Mount Lavinia, Sri Lanka', 'Full-Time', '5-7 years', '3-4 years', NULL, NULL, '2026-06-23', '2026-07-17', '1', 'approved', NULL, '4', '2026-06-23 13:32:04', '994', '2026-06-23 13:32:29', NULL, NULL, 'approved', NULL, '2026-06-23 13:26:36', '2026-06-23 13:32:29', NULL, NULL, NULL, NULL, NULL, NULL),
('60', '3', 'GSH/2026/26/004', 'SENIOR ACCOUNTS EXECUTIVE', 'SENIOR ACCOUNTS EXECUTIVE', 'YOUR ROLE:\n\n•Prepare annual budgets and re-forecast periodically to align with business priorities.\n•Finalization of segmental monthly management accounts.\n•Ensure compliance with statutory regulations\n•Liaise with internal and external stakeholders to ensure project alignment.\n•Perform computations and submit statutory returns through IRD portal in compliance with deadlines.\n•Perform periodic reconciliations with other group companies.', 'YOUR PROFILE:\n\n•Bachelor’s Degree in Finance or Accounting from a recognized university or institute and/or partly   qualified in CA or CIMA.\n•Minimum of 04 years’ experience in a similar role.\n•Prior experience in auditing will be considered a distinct advantage.\n•Expertise in taxation, statutory compliance, and financial reporting, complemented by proficiency in   QuickBooks.\n•Ability to work independently and exercise initiative with minimal supervision.', 'qualified in CA or CIMA', 'No. 7E, Postmasters Place, Off Templers Road, Mount Lavinia, Sri Lanka', 'Full-Time', '3-4 years', '3-4 years', NULL, NULL, '2026-06-23', '2026-06-27', '1', 'approved', NULL, '4', '2026-06-23 14:55:44', '994', '2026-06-23 14:56:36', NULL, NULL, 'approved', NULL, '2026-06-23 14:54:29', '2026-06-23 14:56:36', NULL, NULL, NULL, NULL, NULL, NULL),
('68', '1014', 'GSO/2026/27/001', 'Assistant Manager - IT', 'Assistant Manager - IT', '• Lead SAP ERP system support, implementation, and workflow automation across sector companies.\n• Oversee IT infrastructure including servers, networks, CCTV systems, and connectivity across multiple locations.\n• Manage Microsoft 365 (O365), SharePoint, email systems, and user access administration.\n• Ensure data backup, recovery, and IT security compliance across all systems.\n• Handle vendor management and procurement of IT products and services.\n• Develop and implement IT governance, policies, SOPs, and documentation.\n• Monitor voice, data, and internet services for uninterrupted operations.\n• Conduct IT awareness sessions and support end-user training.\n• Support digital transformation and continuous IT process improvements.', '• Bachelor\'s Degree in IT, Computer Science, or related field.\n• Strong knowledge of Microsoft 365, SharePoint, and networking. Knowledge of SAP can be considered an added advantage.\n• Minimum 4 years proven working experience.\n• Experience in CCTV, connectivity, and IT security practices.\n• Good understanding of IT governance and vendor management.\n• Certifications like ITIL / Microsoft / Cisco will be an added advantage.\n• Excellent communication and interpersonal skills to foster relationships with clients and partners.\n• Commitment and desire to achieve personal and company goals.\n• High interpersonal and analytical skills.\n\n\n', 'Degree in IT,Computer Science,or related field', 'No. 439, Galle Road, Colombo 03, Sri Lanka.', 'Full-Time', '1-2 years', '1-2 years', NULL, NULL, '2026-06-30', '2026-07-10', '1', 'approved', NULL, '1000', '2026-06-30 10:05:34', '994', '2026-06-30 10:07:19', NULL, NULL, 'approved', NULL, '2026-06-30 10:04:15', '2026-06-30 10:07:19', NULL, NULL, NULL, NULL, NULL, NULL),
('69', '1014', 'GSO/2026/27/002', 'abc', 'abc', 'abcdzzz', 'abcd', 'software engineering degree', 'No. 439, Galle Road, Colombo 03, Sri Lanka.', 'Full-Time', '1-2 years', '1-2 years', NULL, NULL, '2026-07-02', '2026-07-30', '1', 'approved', NULL, '1000', '2026-07-02 10:28:06', '994', '2026-07-02 10:29:14', NULL, NULL, 'approved', NULL, '2026-07-02 10:17:35', '2026-07-02 10:29:14', NULL, NULL, NULL, NULL, NULL, NULL),
('70', '3', 'GSH/2026/39/005', 'Software Engineer', 'Software Engineer', 'Design, develop, test, and maintain scalable web applications and software solutions.\nDevelop responsive and user-friendly frontend interfaces using modern web technologies.\nBuild and integrate RESTful APIs and backend services.\nWork with relational and NoSQL databases to design, query, and maintain application data.\nCollaborate with UI/UX designers, QA engineers, backend developers, and project managers.\nIdentify and troubleshoot software defects, performance issues, and technical problems.\nParticipate in code reviews and maintain clean, reusable, and well-documented code.\nUse Git/GitHub for source-code management and collaborative development.\nParticipate in Agile/Scrum ceremonies including planning, stand-ups, reviews, and retrospectives.\nResearch and evaluate new technologies that can improve application performance and development processes.', 'Bachelor’s degree or higher diploma in Computer Science, Software Engineering, Information Technology, or a related field.\nKnowledge of at least one programming language such as Java, JavaScript/TypeScript, Python, C#, PHP, or C++.\nExperience or knowledge of frontend technologies such as React, Angular, Vue.js, HTML, CSS, and JavaScript.\nUnderstanding of backend development and RESTful APIs.\nKnowledge of databases such as MySQL, PostgreSQL, MongoDB, or SQL Server.\nFamiliarity with Git and GitHub/GitLab.\nUnderstanding of software development life cycle and Agile methodologies.\nGood problem-solving and analytical skills.\nAbility to work effectively both independently and as part of a team.', '', 'No. 7E, Postmasters Place, Off Templers Road, Mount Lavinia, Sri Lanka', 'Full-Time', '0-1 years', '0-1 years', '50000.00', '80000.00', '2026-09-22', '2026-11-05', '1', 'approved', NULL, NULL, NULL, '994', '2026-10-08 05:37:26', NULL, NULL, 'approved', '994', '2026-09-22 09:01:00', '2026-10-08 11:07:26', NULL, NULL, NULL, NULL, NULL, NULL),
('71', '3', 'GSH/2026/39/006', 'HR Executive', 'HR Executive', '• organized HR Executive to support the company’s day-to-day human resource operations.\n\n• The selected candidate will be responsible for recruitment coordination, employee records, onboarding, attendance management, leave administration, HR documentation, and employee engagement activities.\n\n• This position is suitable for a candidate with a background in Human Resource Management and good communication, organization, and interpersonal skills.', '• Bachelor’s Degree or professional qualification in Human Resource Management, Business Management, or a related field\n• Assist with recruitment and selection activities.\n• Publish job vacancies on recruitment platforms.\n• Screen CVs and shortlist suitable candidates.\n• Schedule interviews and communicate with candidates.\n• Coordinate employee onboarding and orientation programs.\n• Maintain employee personal files and HR records.\n• Prepare appointment letters, confirmation letters, and other HR documents.\n• Monitor employee attendance and leave records.\n• Assist with payroll-related employee information.\n• Support performance appraisal activities.\n• Coordinate training and development programs.\n• Assist with employee engagement activities and company events.\n• Handle employee queries professionally.\n• Maintain confidentiality of employee and organizational information.\n• Prepare HR reports and staff-related documentation.\n• Update employee information in HR systems.\n• Support exit interviews and employee clearance processes.\n• Ensure HR policies and procedures are followed.', '', 'No. 7E, Postmasters Place, Off Templers Road, Mount Lavinia, Sri Lanka', 'Full-Time', '3-4 years', '3-4 years', NULL, NULL, '2026-09-24', '2026-10-22', '1', 'approved', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'approved', '994', '2026-09-24 10:33:02', '2026-09-24 10:33:02', NULL, NULL, NULL, NULL, NULL, NULL),
('72', '3', 'GSH/2026/39/007', 'HEAD OF FINANCE', 'HEAD OF FINANCE', '• Providing strategic leadership to the finance function, in setting and meeting Company objectives.\n• Responsible for financial planning, budgeting, forecasting, statutory compliances and reporting process.\n• Develop and execute financial policies, procedures, and internal controls to ensure compliance with necessary regulatory standards, and Company policies.\n• Monitoring and controlling costs; monitor cashflow, liquidity and manage the working capital.\n• Overseeing the purchasing process and ensuring proper maintenance of inventories and stocks.\n• Analyse financial results against the budgets and take proactive measures to ensure targets are met.\n• Ensure timely periodic financial reports; maintain transparency and integrity in financial reporting.\n• Collaborate with inter-departments to create effective budgets and costings.\n• Manage relationships with banks, external auditors and other key stakeholders.\n• Lead and mentor a team of finance professionals for continuous improvement.', '•Member of ICASL with a degree in Finance/ Accounting.\n•Minimum 3 years experience in a similar role. Experience in a similar industry would be advantageous.\n•Strong leadership skills with a track record of building and developing high-performing teams.\n•Knowledge on corporate finance, accounting principles, tax regulations other applicable regulations and best practices.\n•Proven expertise in strategic planning and analytical skills.\n•Excellent communication and interpersonal skills with the ability to effectively communicate financial insights to non-financial stakeholders.\n•Ability to work independently, prioritize tasks and manage multiple tasks simultaneously', '', 'No. 7E, Postmasters Place, Off Templers Road, Mount Lavinia, Sri Lanka', 'Full-Time', '3-4 years', '3-4 years', NULL, NULL, '2026-09-25', '2026-10-07', '1', 'approved', NULL, NULL, NULL, '1', '2026-09-25 13:31:03', NULL, NULL, 'approved', '4', '2026-09-25 13:30:25', '2026-10-01 12:45:05', NULL, NULL, NULL, NULL, NULL, NULL),
('74', '1014', 'GSO/2026/40/003', 'QA Engineer Intern', 'Associate QA Engineer', '• Review software requirements, specifications, and technical design documents to provide timely, meaningful feedback.\n• Create detailed, comprehensive, and well-structured test plans, test cases, and test scenarios for web and mobile applications.\n• Execute manual functional, regression, smoke, integration, boundary, and negative test cases across different browsers and platforms.\n• Identify, document, track, and thoroughly verify software defects and bugs using Jira.\n• Collaborate closely with software engineers, business analysts, and product managers to clarify requirements and resolve issues promptly.\n• Assist in writing basic test automation scripts and inspecting system logs, database entries, and API responses.\n• Maintain clear, up-to-date QA documentation, test summary reports, and release verification checklists.\n• Participate in agile ceremonies including sprint planning, daily stand-ups, backlog grooming, and retrospective meetings.', '• Bachelor’s degree in Computer Science, Software Engineering, Information Technology, or an equivalent professional qualification (e.g., SLIIT, IIT, NIBM, or similar).\n• 0–2 years of hands-on experience in Quality Assurance, Software Testing, or an internship in a software development environment.\n• Solid understanding of software QA methodologies, tools, processes, and the Software Testing Life Cycle (STLC / SDLC).\n• Hands-on familiarity with defect tracking and project management tools, primarily Jira.\n• Basic coding/scripting knowledge in one or more languages (e.g., Python, JavaScript, Java, or C#) with an interest in test automation.\n• Basic understanding of web technologies, REST APIs (e.g., Postman), and database querying (SQL).\n• Proven ability to write clear, concise, and structured test documentation and bug reports.\n• Strong analytical, problem-solving, and attention-to-detail skills.\n• Excellent verbal and written communication skills in English.\n• ISTQB Certified Tester Foundation Level (CTFL) certification is an added advantage.', 'Coding,QA,Jira', 'No. 439, Galle Road, Colombo 03, Sri Lanka.', 'Internship', '1-2 years', '0-1 years', NULL, NULL, '2026-10-01', '2026-10-09', '1', 'approved', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'approved', '994', '2026-10-01 13:01:11', '2026-10-05 10:36:12', NULL, NULL, NULL, NULL, NULL, NULL),
